<?php
namespace App\Http\Controllers\Api\V1;
use App\Enums\BookingStatus; use App\Http\Controllers\Controller; use App\Models\{Booking,Payment,PaymentTransaction}; use App\Services\Audit; use Illuminate\Http\{JsonResponse,Request}; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
class PaymentController extends Controller {
 public function initialize(Request $r,Booking $booking):JsonResponse{abort_unless($booking->customer_id===$r->user()->id&&$booking->status===BookingStatus::Confirmed,403);$quote=$booking->quotation()->firstOrFail();$d=$r->validate(['provider'=>'required|in:paystack,flutterwave']);$payment=Payment::firstOrCreate(['booking_id'=>$booking->id],['provider'=>$d['provider'],'provider_reference'=>'FXPAY-'.Str::uuid(),'amount_minor'=>$quote->amount_minor,'currency'=>$quote->currency,'status'=>'pending']);return response()->json(['data'=>$payment,'message'=>'Create the provider checkout session server-side using this reference.']);}
 public function webhook(Request $r,string $provider):JsonResponse{$secret=(string)config("services.{$provider}.webhook_secret");abort_if($secret===''||!hash_equals(hash_hmac('sha512',$r->getContent(),$secret),(string)$r->header('X-Fixifier-Signature')),401);$d=$r->validate(['reference'=>'required|string','status'=>'required|in:authorized,failed','amount_minor'=>'required|integer|min:1']);DB::transaction(function()use($d,$provider,$r){$p=Payment::where('provider_reference',$d['reference'])->lockForUpdate()->firstOrFail();abort_unless($p->amount_minor===(int)$d['amount_minor']&&$p->provider===$provider,422);PaymentTransaction::firstOrCreate(['provider_reference'=>$d['reference'].'-'.$d['status']],['payment_id'=>$p->id,'type'=>'authorization','amount_minor'=>$p->amount_minor,'status'=>$d['status'],'payload'=>$r->all()]);if($p->status==='pending')$p->update(['status'=>$d['status'],'authorized_at'=>$d['status']==='authorized'?now():null]);Audit::record('payment.webhook',$p,['status'=>$d['status']]);});return response()->json(['received'=>true]);}
}
